import React, { useRef, useEffect } from 'react';

// Softer, more organic sphere — flows like water, not like a technical wireframe
export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5, dark = false }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2, r = size * 0.4;

    const lineColor = dark
      ? (a) => `rgba(28,25,23,${a})`
      : (a) => `rgba(28,25,23,${a})`;

    const draw = () => {
      t.current += 0.0035 * speed;
      ctx.clearRect(0, 0, size, size);

      const lats = 14, lons = 20;

      // Subtle glow halo behind sphere
      const halo = ctx.createRadialGradient(cx, cy, r * 0.3, cx, cy, r * 1.4);
      halo.addColorStop(0, dark ? 'rgba(28,25,23,0.07)' : 'rgba(150,130,180,0.12)');
      halo.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(cx, cy, r * 1.4, 0, Math.PI * 2);
      ctx.fillStyle = halo; ctx.fill();

      const project = (lat, lon) => {
        const phi   = (lat / lats) * Math.PI;
        const theta = (lon / lons) * Math.PI * 2 + t.current;
        const warp  = 1
          + Math.sin(phi * 2 + t.current * 0.5)  * 0.06 * distort
          + Math.cos(theta * 1.5 + t.current * 0.7) * 0.04 * distort
          + Math.sin(phi * 4 + theta + t.current * 0.3) * 0.02 * distort;
        const sr = r * warp;
        return {
          x: cx + sr * Math.sin(phi) * Math.cos(theta),
          y: cy + sr * Math.cos(phi),
          z: sr * Math.sin(phi) * Math.sin(theta),
        };
      };

      // Latitude lines
      for (let lat = 0; lat <= lats; lat++) {
        const pts = Array.from({length: lons + 1}, (_, lon) => project(lat, lon));
        for (let i = 0; i < pts.length - 1; i++) {
          const dz = ((pts[i].z + pts[i+1].z) / 2 / r + 1) / 2;
          const alpha = (0.04 + dz * 0.28) * (lat === 0 || lat === lats ? 0 : 1);
          if (alpha < 0.01) continue;
          ctx.beginPath();
          ctx.moveTo(pts[i].x, pts[i].y);
          ctx.lineTo(pts[i+1].x, pts[i+1].y);
          ctx.strokeStyle = lineColor(alpha);
          ctx.lineWidth = 0.5 + dz * 0.5;
          ctx.stroke();
        }
      }

      // Longitude lines
      for (let lon = 0; lon < lons; lon++) {
        const pts = Array.from({length: lats + 1}, (_, lat) => project(lat, lon));
        for (let i = 0; i < pts.length - 1; i++) {
          const dz = ((pts[i].z + pts[i+1].z) / 2 / r + 1) / 2;
          const alpha = 0.03 + dz * 0.22;
          ctx.beginPath();
          ctx.moveTo(pts[i].x, pts[i].y);
          ctx.lineTo(pts[i+1].x, pts[i+1].y);
          ctx.strokeStyle = lineColor(alpha);
          ctx.lineWidth = 0.4 + dz * 0.4;
          ctx.stroke();
        }
      }

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort, dark]);

  return <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />;
}
